export function DashboardUserMenu({
  collapsed = false,
  suppressHover = false,
  onHoverSuppressionEnd,
  avatarClassName,
  account = DEFAULT_DASHBOARD_ACCOUNT,
  users,
}: {
  collapsed?: boolean;
  /** Prevents expansion from creating a hover state under a stationary pointer. */
  suppressHover?: boolean;
  /** Re-arms hover after the pointer fully leaves the trigger. */
  onHoverSuppressionEnd?: () => void;
  avatarClassName?: string;
  account?: DashboardAccount;
  users?: DashboardAccount[];
}) {
  const [isOpen, setIsOpen] = useState(false);
  // "right" placement assumes room to the sidebar's right (true in-flow on
  // desktop) — on mobile the sidebar can span the full viewport, so the
  // 265px panel would render off-screen. Below sm, drop into a plain
  // dropdown under the trigger instead.
  const [isMobile, setIsMobile] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(max-width: 639px)");
    setIsMobile(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setIsMobile(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  return (
    <AriaDialogTrigger isOpen={isOpen} onOpenChange={setIsOpen}>
      <AriaButton
        aria-label={account.name}
        onPointerLeave={() => {
          if (suppressHover) onHoverSuppressionEnd?.();
        }}
        className={cx(
          "relative flex min-w-0 cursor-pointer items-center gap-2 rounded-full outline-none",
          "focus-visible:ring-2 focus-visible:ring-border-focus-ring focus-visible:ring-offset-2",
          // A fully-rounded 2px border/button/hover
          // outline drawn via a pseudo-element so it never shifts the layout.
          "before:pointer-events-none before:absolute before:-inset-x-1.5 before:-inset-y-[5px] before:rounded-full before:border-2 before:border-transparent before:transition-colors before:duration-150",
          !suppressHover && "hover:before:border-border-sidebar-profile-hover",
          // Collapsed, the trigger takes the rail's own 36px column and centres
          // the 32px avatar in it, instead of sizing to the avatar plus a gap
          // held open for a label that's shrunk to nothing. That gap made the
          // button 42px wide in a 36px rail, which pushed its hover pill
          // off-centre and into the rail's clip.
          //
          // The pill's insets go square too: 36×32 plus the expanded 6/5 reach
          // is a 48×42 stadium, not the circle the avatar wants. 3/5 lands it
          // on 42×42.
          collapsed && "w-9 justify-center gap-0 before:-inset-x-[3px]",
        )}
      >
        <Avatar
          size="md"
          color={account.color}
          initials={account.initials}
          className={avatarClassName}
        />
        <Collapsible collapsed={collapsed}>
          <span className="flex items-center gap-0.5">
            <span className="text-body-medium whitespace-nowrap text-text-primary">
              {account.name}
            </span>
            <ChevronUpDownSmall className="size-4 shrink-0 text-foreground-icon-tertiary" />
          </span>
        </Collapsible>
      </AriaButton>

      <AriaPopover
        placement={isMobile ? "bottom start" : "right top"}
        offset={8}
        className={cx(
          "w-[265px] max-w-[calc(100vw-32px)] origin-top-left overflow-y-auto",
          "rounded-2xl border border-border-button-default bg-background-primary-default p-2.5 shadow-dropdown",
          "transition duration-150 ease-out",
          "data-[entering]:opacity-0 data-[entering]:scale-95 data-[entering]:blur-[2px]",
          "data-[exiting]:opacity-0 data-[exiting]:scale-95 data-[exiting]:blur-[2px]",
        )}
      >
        <AriaDialog aria-label="Account menu" className="flex flex-col outline-none">
          <AccountMenuContent onSelect={() => setIsOpen(false)} users={users} />
        </AriaDialog>
      </AriaPopover>
    </AriaDialogTrigger>
  );
}

// @zeus-internal
"use client";
import { useEffect, useState } from "react";
import type { SettingsMarketplaceProps } from "./settings-marketplace";
import { DEFAULT_MARKETPLACE_ITEMS } from "./marketplace-data";
export function useMarketplaceInstallation({
  items = DEFAULT_MARKETPLACE_ITEMS,
  installedIds,
  onInstalledChange,
  storageKey = "zeus:marketplace:v1",
}: Omit<SettingsMarketplaceProps, "onClose"> = {}) {
  const [local, setLocal] = useState(() =>
    items.filter((item) => item.installed).map((item) => item.id),
  );
  const controlled = installedIds !== undefined;
  useEffect(() => {
    if (controlled || !storageKey) return;
    const read = () => {
      try {
        const raw = localStorage.getItem(storageKey);
        if (!raw) return;
        const ids: unknown = JSON.parse(raw);
        if (Array.isArray(ids) && ids.every((id) => typeof id === "string")) setLocal(ids);
      } catch {}
    };
    read();
    window.addEventListener("storage", read);
    window.addEventListener("zeus-marketplace-change", read);
    return () => {
      window.removeEventListener("storage", read);
      window.removeEventListener("zeus-marketplace-change", read);
    };
  }, [controlled, storageKey]);
  return {
    installed: installedIds ?? local,
    change: (ids: string[]) => {
      if (!controlled) {
        setLocal(ids);
        if (storageKey)
          try {
            localStorage.setItem(storageKey, JSON.stringify(ids));
            window.dispatchEvent(new Event("zeus-marketplace-change"));
          } catch {}
      }
      onInstalledChange?.(ids);
    },
  };
}

"use client";
import { useRef, useState, type ReactNode } from "react";
import {
  RiCheckLine,
  RiArrowRightSLine,
  RiCodeBoxLine,
  RiGlobalLine,
  RiLink,
  RiPlugLine,
  RiSearchLine,
} from "@remixicon/react";
import { Button, ButtonLink } from "../../base/buttons/button";
import { Input } from "../../base/input/input";
import { PillTab, PillTabList } from "../../base/tabs/pill-tab";
import { CardSurface, cardSurfaceClasses } from "../charts/card-surface";
import { AgentAvatar, type AgentAvatarProps } from "../agent-creator/agent-avatar";
import { SettingsPageHeader } from "./settings-page-header";
import { useMarketplaceInstallation } from "./marketplace-installation";
import { DEFAULT_MARKETPLACE_ITEMS } from "./marketplace-data";
export interface MarketplaceItem {
  id: string;
  kind: "bot" | "plugin";
  name: string;
  category: string;
  description: string;
  detail?: string;
  color?: string;
  shape?: AgentAvatarProps["shape"];
  icon?: ReactNode;
  installed?: boolean;
  website?: string;
  skill?: { name: string; description: string };
}
export interface SettingsMarketplaceProps {
  onClose: () => void;
  items?: readonly MarketplaceItem[];
  installedIds?: readonly string[];
  /** Browser-local demo installation state; null disables persistence. */
  storageKey?: string | null;
  onInstalledChange?: (ids: string[]) => void;
}
type Category = "Discover" | "Plugins" | "Bots" | "Installed";
/** Searchable workspace extensions and agent cards, with host-owned installation callbacks. */
export function SettingsMarketplace({
  onClose,
  items = DEFAULT_MARKETPLACE_ITEMS,
  installedIds,
  onInstalledChange,
  storageKey,
}: SettingsMarketplaceProps) {
  const [category, setCategory] = useState<Category>("Discover"),
    [query, setQuery] = useState(""),
    [selectedId, setSelectedId] = useState<string | null>(null);
  const { installed, change } = useMarketplaceInstallation({
    items,
    installedIds,
    onInstalledChange,
    storageKey,
  });
  const [copied, setCopied] = useState(false);
  const selected = items.find((i) => i.id === selectedId);
  const scroll = useRef<HTMLDivElement>(null);
  const changeCategory = (next: Category) => {
    setCategory(next);
    setSelectedId(null);
    if (scroll.current) scroll.current.scrollTop = 0;
  };
  const install = (item: MarketplaceItem) => {
    const next = installed.includes(item.id)
      ? installed.filter((id) => id !== item.id)
      : [...installed, item.id];
    change(next);
  };
  const open = (item: MarketplaceItem) => {
    setSelectedId(item.id);
    setCopied(false);
    if (scroll.current) scroll.current.scrollTop = 0;
  };
  const filtered = items.filter((i) =>
    `${i.name} ${i.category} ${i.description}`.toLowerCase().includes(query.toLowerCase().trim()),
  );
  const bots = filtered.filter((i) => i.kind === "bot"),
    plugins = filtered.filter((i) => i.kind === "plugin");
  const addButton = (item: MarketplaceItem, primary = false) => (
    <Button
      size={primary ? "medium" : "small"}
      variant={primary && !installed.includes(item.id) ? "primary" : "secondary"}
      className="mt-auto w-full shrink-0 rounded-full"
      aria-label={`${installed.includes(item.id) ? (primary ? "Remove" : "View added") : "Add"} ${item.name}`}
      onClick={() => (installed.includes(item.id) && !primary ? open(item) : install(item))}
    >
      {installed.includes(item.id) ? (primary ? "Remove" : "Added") : "Add"}
    </Button>
  );
  const grid = (entries: MarketplaceItem[]) => (
    <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
      {entries.map((item) => (
        <MarketplaceCard key={item.id} item={item} onOpen={() => open(item)}>
          {addButton(item)}
        </MarketplaceCard>
      ))}
    </div>
  );
  return (
    <>
      <SettingsPageHeader
        title="Marketplace"
        roundClose
        onClose={onClose}
        onBack={selected ? () => setSelectedId(null) : undefined}
        className="px-4 pb-4 sm:px-8"
      />
      {!selected && (
        <div className="flex shrink-0 flex-col gap-3 px-4 pb-4 sm:px-8">
          <Input
            aria-label="Search marketplace"
            placeholder="Find your next tool or teammate"
            leadingIcon={RiSearchLine}
            value={query}
            onChange={setQuery}
            fieldClassName="rounded-xl bg-background-secondary-default shadow-none"
          />
          <PillTabList aria-label="Marketplace categories" className="w-fit max-w-full flex-wrap">
            {(["Discover", "Plugins", "Bots", "Installed"] as const).map((tab) => (
              <PillTab
                key={tab}
                variant="gray"
                isSelected={category === tab}
                onSelect={() => changeCategory(tab)}
              >
                {tab}
              </PillTab>
            ))}
          </PillTabList>
        </div>
      )}
      <div className="relative min-h-0 flex-1">
        <div
          ref={scroll}
          aria-label={selected ? `${selected.name} details` : "Marketplace results"}
          tabIndex={0}
          className="h-full overflow-y-auto overscroll-contain px-4 pb-8 outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-border-focus-ring [scrollbar-width:none] sm:px-8"
        >
          <div className="flex flex-col gap-5 pt-1">
            {selected ? (
              <>
                <CardSurface
                  padding="none"
                  className="flex w-full flex-col items-center gap-4 p-5 text-center"
                >
                  <MarketplaceIcon item={selected} large />
                  <div className="flex flex-col items-center gap-1">
                    <h2 className="text-title-3-semibold text-text-primary">{selected.name}</h2>
                    <span className="text-body-2-regular text-text-secondary">
                      {selected.category}
                    </span>
                  </div>
                  <p className="text-body-regular text-text-secondary">
                    {selected.detail ?? selected.description}
                  </p>
                  <div className="grid w-full grid-cols-2 gap-2 sm:grid-cols-3">
                    {addButton(selected, true)}
                    <Button
                      variant="secondary"
                      className="w-full rounded-full"
                      leadingIcon={copied ? RiCheckLine : RiLink}
                      onClick={async () => {
                        try {
                          await navigator.clipboard.writeText(
                            selected.website ??
                              `${location.origin}${location.pathname}#marketplace-${encodeURIComponent(selected.id)}`,
                          );
                          setCopied(true);
                        } catch {
                          setCopied(false);
                        }
                      }}
                    >
                      {copied ? "Copied" : "Share"}
                    </Button>
                    {selected.website ? (
                      <ButtonLink
                        href={selected.website}
                        target="_blank"
                        rel="noreferrer"
                        variant="secondary"
                        leadingIcon={RiGlobalLine}
                        className="col-span-2 row-start-2 w-full rounded-full sm:col-span-1 sm:row-start-auto"
                      >
                        Website
                      </ButtonLink>
                    ) : (
                      <Button
                        disabled
                        variant="secondary"
                        leadingIcon={RiGlobalLine}
                        className="col-span-2 row-start-2 w-full rounded-full sm:col-span-1 sm:row-start-auto"
                      >
                        Website
                      </Button>
                    )}
                  </div>
                </CardSurface>
                {selected.skill && (
                  <section className="flex flex-col gap-1">
                    <p className="px-3 text-body-2-medium text-text-secondary">Skills · 1</p>
                    <CardSurface padding="none" className="flex items-center gap-3 p-3">
                      <RiCodeBoxLine
                        aria-hidden
                        className="size-5 shrink-0 text-foreground-icon-secondary"
                      />
                      <div className="flex min-w-0 flex-col gap-1">
                        <h3 className="text-body-medium text-text-primary">
                          {selected.skill.name}
                        </h3>
                        <p className="text-body-2-regular text-text-secondary">
                          {selected.skill.description}
                        </p>
                      </div>
                    </CardSurface>
                  </section>
                )}
                <section className="flex flex-col gap-1">
                  <p className="px-3 text-body-2-medium text-text-secondary">Details</p>
                  <CardSurface padding="uniform" className="grid grid-cols-2 gap-4">
                    {[
                      ["Category", selected.category],
                      [
                        "Includes",
                        selected.skill ? "1 skill" : selected.kind === "bot" ? "Agent" : "Plugin",
                      ],
                      ["Availability", "Public"],
                    ].map(([label, value]) => (
                      <div key={label} className="flex flex-col gap-1">
                        <span className="text-body-2-regular text-text-secondary">{label}</span>
                        <span className="text-body-regular text-text-primary">{value}</span>
                      </div>
                    ))}
                  </CardSurface>
                </section>
              </>
            ) : category === "Discover" ? (
              <>
                <MarketplaceSection
                  title="Meet your next teammate"
                  onViewAll={() => changeCategory("Bots")}
                >
                  <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
                    {bots.slice(0, 4).map((item) => (
                      <Button
                        unstyled
                        key={item.id}
                        aria-label={`View ${item.name}`}
                        onClick={() => open(item)}
                        className={`${cardSurfaceClasses({ padding: "none" })} flex min-w-0 flex-col items-center gap-2 px-2 py-4 text-center outline-none transition-colors hover:bg-background-tertiary-default focus-visible:ring-2 focus-visible:ring-border-focus-ring`}
                      >
                        <MarketplaceIcon item={item} featured />
                        <span className="flex flex-col gap-1">
                          <span className="text-body-2-medium text-text-primary">{item.name}</span>
                          <span className="text-caption-1-regular text-text-secondary">
                            {item.category}
                          </span>
                        </span>
                      </Button>
                    ))}
                  </div>
                </MarketplaceSection>
                <MarketplaceSection
                  title="Tools for your workflow"
                  onViewAll={() => changeCategory("Plugins")}
                >
                  {grid(plugins.filter((i) => !i.installed).slice(0, 4))}
                </MarketplaceSection>
                <MarketplaceSection title="Everyday essentials">
                  {grid(plugins.filter((i) => i.installed))}
                </MarketplaceSection>
              </>
            ) : (
              <MarketplaceSection
                title={
                  category === "Plugins"
                    ? "Explore plugins"
                    : category === "Bots"
                      ? "Find your next teammate"
                      : "Added to your workspace"
                }
              >
                {grid(
                  category === "Plugins"
                    ? plugins
                    : category === "Bots"
                      ? bots
                      : filtered.filter((i) => installed.includes(i.id)),
                )}
              </MarketplaceSection>
            )}
            {!selected && filtered.length === 0 && (
              <p className="py-8 text-center text-body-regular text-text-secondary">
                No results found
              </p>
            )}
          </div>
        </div>
      </div>
    </>
  );
}
function MarketplaceIcon({
  item,
  large = false,
  featured = false,
}: {
  item: MarketplaceItem;
  large?: boolean;
  featured?: boolean;
}) {
  return item.kind === "bot" ? (
    <AgentAvatar
      color={item.color}
      shape={item.shape}
      className={large ? "size-[72px]" : featured ? "size-[52px]" : "size-9"}
    />
  ) : (
    <span
      className={`${large ? "size-[72px]" : "size-9"} flex shrink-0 items-center justify-center rounded-xl border border-border-button-default bg-background-primary-default text-foreground-icon-secondary`}
    >
      {item.icon ?? <RiPlugLine className={large ? "size-9" : "size-5"} aria-hidden />}
    </span>
  );
}
export function MarketplaceCard({
  item,
  onOpen,
  children,
}: {
  item: MarketplaceItem;
  onOpen: () => void;
  children: ReactNode;
}) {
  return (
    <CardSurface
      padding="none"
      className="group flex min-w-0 flex-col gap-3 p-3 transition-colors hover:bg-background-secondary-hover"
    >
      <Button
        unstyled
        onClick={onOpen}
        aria-label={`View ${item.name}`}
        className="flex min-w-0 items-center gap-3 rounded-lg text-start outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring"
      >
        <MarketplaceIcon item={item} />
        <span className="flex min-w-0 flex-col gap-0.5">
          <span className="text-body-medium text-text-primary">{item.name}</span>
          <span className="text-caption-1-regular text-text-tertiary">{item.category}</span>
        </span>
      </Button>
      <p className="text-body-2-regular text-text-secondary">{item.description}</p>
      {children}
    </CardSurface>
  );
}
function MarketplaceSection({
  title,
  onViewAll,
  children,
}: {
  title: string;
  onViewAll?: () => void;
  children: ReactNode;
}) {
  return (
    <section className="flex flex-col gap-1">
      <div className="flex h-8 items-center justify-between px-2">
        <h2 className="text-body-medium text-text-primary">{title}</h2>
        {onViewAll && (
          <Button
            size="small"
            variant="ghost"
            trailingIcon={RiArrowRightSLine}
            onClick={onViewAll}
            aria-label={`View all ${title.toLowerCase()}`}
            className="bg-transparent text-text-secondary hover:bg-background-secondary-default active:bg-background-tertiary-default"
          >
            View all
          </Button>
        )}
      </div>
      {children}
    </section>
  );
}

